    jsonb_build_object('key','idama_blend_vanadium_ppm', 'label','Vanadium content of the cargo', 'unit','ppm', 'expected',14.946944991453488, 'tol',5e-05),
    jsonb_build_object('key','idama_abiteye_mass_share_pct', 'label','Abiteye Heavy''s share of the cargo by mass', 'unit','percent', 'expected',17.175715682949974, 'tol',5e-05),
    jsonb_build_object('key','idama_blend_cii', 'label','Colloidal instability index of the cargo', 'unit','index', 'expected',1.0443475502291177, 'tol',5e-05),
    jsonb_build_object('key','idama_opuama_kerosene_yield_pct', 'label','Kerosene / Jet yield of Opuama Medium alone', 'unit','volume percent', 'expected',15.246859479988313, 'tol',5e-05)
  )
),
(
  'crude', 'intermediate', 'professional',
  'OGBELE, an invented modular refinery valuing a blend of two invented crudes on its own cut set',
  'The blended barrel and its netback',
  'OGBELE MODULAR REFINERY. The refinery is offered a blend of two crudes. Every figure is invented and illustrative. Ogbele Light: 62 percent of the blend by volume, API 39.7, TBP curve 0 percent at 72 F, 10 percent at 182 F, 30 percent at 355 F, 50 percent at 515 F, 70 percent at 705 F, 90 percent at 1010 F, 100 percent at 1330 F. Omoku Medium: 38 percent of the blend by volume, API 26.2, TBP curve 0 percent at 98 F, 10 percent at 285 F, 30 percent at 505 F, 50 percent at 675 F, 70 percent at 885 F, 90 percent at 1225 F, 100 percent at 1490 F. The refinery''s cut set and product prices: LPG / Light ends up to 90 F, priced at 46.5 dollars per bbl; Naphtha 90 F to 340 F, priced at 71.2 dollars per bbl; Kerosene / DPK 340 F to 470 F, priced at 94.6 dollars per bbl; Diesel / AGO 470 F to 640 F, priced at 99.3 dollars per bbl; Atmospheric residue 640 F to the end of the curve, priced at 54.8 dollars per bbl. Processing costs 7.35 dollars per bbl of crude, freight to the refinery 2.15 dollars per bbl, and losses are 1.1 percent, taken on the product side. Give six numbers, each to four decimals. (1) The temperature at which the blend''s own TBP curve reaches 50 percent, in F. (2) The blend''s Kerosene / DPK yield, in volume percent. (3) The blend''s Diesel / AGO yield, in volume percent. (4) The gross product value per bbl of blend. (5) The value lost to losses per bbl of blend. (6) The netback per bbl of blend.',
  jsonb_build_array(
    jsonb_build_object('key','ogbele_blend_t50_f', 'label','Temperature at which the blend''s own TBP curve reaches half distilled', 'unit','F', 'expected',580.0450450450451, 'tol',5e-05),
    jsonb_build_object('key','ogbele_blend_kerosene_yield_pct', 'label','Kerosene / DPK yield of the blend', 'unit','volume percent', 'expected',14.478553599579609, 'tol',5e-05),
    jsonb_build_object('key','ogbele_blend_diesel_yield_pct', 'label','Diesel / AGO yield of the blend', 'unit','volume percent', 'expected',18.889779763580073, 'tol',5e-05),
    jsonb_build_object('key','ogbele_gross_value_per_bbl', 'label','Gross product value per bbl of blend', 'unit','dollars per bbl', 'expected',72.52669990073112, 'tol',5e-05),
    jsonb_build_object('key','ogbele_loss_value_per_bbl', 'label','Value lost to losses per bbl of blend', 'unit','dollars per bbl', 'expected',0.7977936989080376, 'tol',5e-05),
    jsonb_build_object('key','ogbele_netback_per_bbl', 'label','Netback per bbl of blend', 'unit','dollars per bbl', 'expected',62.22890620182309, 'tol',5e-05)
  )
