    jsonb_build_object('key','onne_butane_volume_bbl', 'label','Butane in the least-cost recipe', 'unit','bbl', 'expected',437.0326736147707, 'tol',5e-05),
    jsonb_build_object('key','onne_sulfur_relief_usd_per_ppm', 'label','Value of relief on the sulfur limit, at the margin', 'unit','dollars per ppm', 'expected',296.3096164435926, 'tol',5e-05),
    jsonb_build_object('key','onne_rvp_relief_usd_per_psi', 'label','Value of relief on the RVP limit, at the margin', 'unit','dollars per psi', 'expected',6495.117849392539, 'tol',5e-05),
    jsonb_build_object('key','onne_ron_relief_usd_per_octane', 'label','Value of relief on the RON minimum, at the margin', 'unit','dollars per octane number', 'expected',4032.630838167829, 'tol',5e-05)
  )
